import { getContext, setContext, SvelteComponent } from 'svelte';
const themeKey = Symbol();
export function createTheme(theme) {
    setContext(themeKey, theme);
}
export function getTheme() {
    return getContext(themeKey) ?? {};
}
export function getComponentTheme(name) {
    const theme = getTheme()[name] ?? {};
    return typeof theme === 'string' ? { root: theme } : theme;
}
